-- Phase 5: agency services, project delivery, proposals, invoices, and notifications.
CREATE TYPE "ServiceStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "ProjectRequestStatus" AS ENUM ('DRAFT','SUBMITTED','UNDER_REVIEW','NEEDS_INFORMATION','QUOTED','ACCEPTED','DECLINED','CANCELLED');
CREATE TYPE "ProjectStatus" AS ENUM ('AWAITING_DEPOSIT','PLANNING','DESIGN','DEVELOPMENT','TESTING','CLIENT_REVIEW','COMPLETED','ON_HOLD','CANCELLED');
CREATE TYPE "ProposalStatus" AS ENUM ('DRAFT','SENT','VIEWED','ACCEPTED','REJECTED','EXPIRED','SUPERSEDED');
CREATE TYPE "MilestoneStatus" AS ENUM ('PENDING','IN_PROGRESS','READY_FOR_REVIEW','APPROVED','CHANGES_REQUESTED','COMPLETED');
CREATE TYPE "ApprovalStatus" AS ENUM ('PENDING','APPROVED','CHANGES_REQUESTED');
CREATE TYPE "ProjectInvoiceStatus" AS ENUM ('DRAFT','ISSUED','PARTIALLY_PAID','PAID','OVERDUE','VOID');
CREATE TYPE "ProjectPaymentStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "ProjectFileVisibility" AS ENUM ('CLIENT','INTERNAL');

ALTER TABLE "Service" ADD COLUMN "status" "ServiceStatus" NOT NULL DEFAULT 'DRAFT', ADD COLUMN "category" TEXT NOT NULL DEFAULT 'Custom Web Application', ADD COLUMN "includedFeatures" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "estimatedDeliveryDays" INTEGER, ADD COLUMN "startingPriceMmk" INTEGER, ADD COLUMN "customQuotation" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "faq" JSONB, ADD COLUMN "ctaText" TEXT;
UPDATE "Service" SET "status"='PUBLISHED' WHERE "isActive"=true;
CREATE INDEX "Service_status_createdAt_idx" ON "Service"("status","createdAt");

CREATE TABLE "ProjectRequest" ("id" UUID NOT NULL,"requestNumber" TEXT NOT NULL,"customerId" UUID NOT NULL,"assignedAdminId" UUID,"status" "ProjectRequestStatus" NOT NULL DEFAULT 'DRAFT',"companyName" TEXT,"websiteType" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"requiredPages" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"requiredFeatures" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"preferredTechnology" TEXT,"budgetMinMmk" INTEGER,"budgetMaxMmk" INTEGER,"desiredDeadline" TIMESTAMP(3),"referenceUrls" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"additionalNotes" TEXT,"internalNotes" TEXT,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"submittedAt" TIMESTAMP(3),CONSTRAINT "ProjectRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectRequestAttachment" ("id" UUID NOT NULL,"requestId" UUID NOT NULL,"storageKey" TEXT NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProjectRequestAttachment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Proposal" ("id" UUID NOT NULL,"proposalNumber" TEXT NOT NULL,"requestId" UUID NOT NULL,"clientId" UUID NOT NULL,"createdById" UUID NOT NULL,"acceptedById" UUID,"status" "ProposalStatus" NOT NULL DEFAULT 'DRAFT',"currentVersionNumber" INTEGER NOT NULL DEFAULT 1,"acceptedAt" TIMESTAMP(3),"acceptedTermsSnapshot" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Proposal_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProposalVersion" ("id" UUID NOT NULL,"proposalId" UUID NOT NULL,"versionNumber" INTEGER NOT NULL,"projectScope" TEXT NOT NULL,"deliverables" TEXT[] NOT NULL,"technologyStack" TEXT[] NOT NULL,"estimatedTimeline" TEXT NOT NULL,"subtotalMmk" INTEGER NOT NULL,"discountMmk" INTEGER NOT NULL DEFAULT 0,"totalMmk" INTEGER NOT NULL,"paymentSchedule" JSONB NOT NULL,"termsAndConditions" TEXT NOT NULL,"expirationDate" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProposalVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProposalItem" ("id" UUID NOT NULL,"versionId" UUID NOT NULL,"description" TEXT NOT NULL,"quantity" INTEGER NOT NULL DEFAULT 1,"unitPriceMmk" INTEGER NOT NULL,"totalMmk" INTEGER NOT NULL,CONSTRAINT "ProposalItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" UUID NOT NULL,"projectNumber" TEXT NOT NULL,"requestId" UUID NOT NULL,"proposalId" UUID NOT NULL,"clientId" UUID NOT NULL,"assignedAdminId" UUID,"status" "ProjectStatus" NOT NULL DEFAULT 'AWAITING_DEPOSIT',"budgetMmk" INTEGER NOT NULL,"startDate" TIMESTAMP(3),"targetCompletionDate" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectMilestone" ("id" UUID NOT NULL,"projectId" UUID NOT NULL,"ownerId" UUID,"name" TEXT NOT NULL,"description" TEXT,"weight" INTEGER NOT NULL,"status" "MilestoneStatus" NOT NULL DEFAULT 'PENDING',"dueDate" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProjectMilestone_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectApproval" ("id" UUID NOT NULL,"projectId" UUID NOT NULL,"milestoneId" UUID NOT NULL,"actorId" UUID NOT NULL,"status" "ApprovalStatus" NOT NULL,"note" TEXT,"actedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProjectApproval_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectMessage" ("id" UUID NOT NULL,"projectId" UUID NOT NULL,"authorId" UUID NOT NULL,"body" TEXT NOT NULL,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProjectMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectMessageAttachment" ("id" UUID NOT NULL,"messageId" UUID NOT NULL,"storageKey" TEXT NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProjectMessageAttachment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectFile" ("id" UUID NOT NULL,"projectId" UUID NOT NULL,"uploadedById" UUID NOT NULL,"category" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"fileName" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"checksum" TEXT NOT NULL,"visibility" "ProjectFileVisibility" NOT NULL DEFAULT 'CLIENT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProjectFile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectFileEvent" ("id" UUID NOT NULL,"fileId" UUID NOT NULL,"userId" UUID NOT NULL,"action" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProjectFileEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectActivity" ("id" UUID NOT NULL,"projectId" UUID NOT NULL,"actorId" UUID,"action" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProjectActivity_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectInvoice" ("id" UUID NOT NULL,"projectId" UUID NOT NULL,"clientId" UUID NOT NULL,"invoiceNumber" TEXT NOT NULL,"status" "ProjectInvoiceStatus" NOT NULL DEFAULT 'DRAFT',"subtotalMmk" INTEGER NOT NULL,"totalMmk" INTEGER NOT NULL,"amountPaidMmk" INTEGER NOT NULL DEFAULT 0,"dueDate" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProjectInvoice_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectInvoiceItem" ("id" UUID NOT NULL,"invoiceId" UUID NOT NULL,"description" TEXT NOT NULL,"amountMmk" INTEGER NOT NULL,CONSTRAINT "ProjectInvoiceItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectPaymentSubmission" ("id" UUID NOT NULL,"invoiceId" UUID NOT NULL,"paymentMethodId" UUID NOT NULL,"submittedById" UUID NOT NULL,"amountMmk" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'MMK',"transactionReference" TEXT NOT NULL,"proofStorageKey" TEXT NOT NULL,"proofMimeType" TEXT NOT NULL,"status" "ProjectPaymentStatus" NOT NULL DEFAULT 'PENDING',"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProjectPaymentSubmission_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectPaymentReview" ("id" UUID NOT NULL,"submissionId" UUID NOT NULL,"reviewerId" UUID NOT NULL,"decision" "ProjectPaymentStatus" NOT NULL,"rejectionReason" TEXT,"reviewedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProjectPaymentReview_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Notification" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"href" TEXT,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "ProjectRequest_requestNumber_key" ON "ProjectRequest"("requestNumber");CREATE UNIQUE INDEX "ProjectRequest_customerId_idempotencyKey_key" ON "ProjectRequest"("customerId","idempotencyKey");CREATE INDEX "ProjectRequest_status_createdAt_idx" ON "ProjectRequest"("status","createdAt");CREATE INDEX "ProjectRequest_customerId_createdAt_idx" ON "ProjectRequest"("customerId","createdAt");
CREATE UNIQUE INDEX "Proposal_proposalNumber_key" ON "Proposal"("proposalNumber");CREATE INDEX "Proposal_clientId_status_createdAt_idx" ON "Proposal"("clientId","status","createdAt");CREATE INDEX "Proposal_requestId_createdAt_idx" ON "Proposal"("requestId","createdAt");CREATE UNIQUE INDEX "ProposalVersion_proposalId_versionNumber_key" ON "ProposalVersion"("proposalId","versionNumber");CREATE INDEX "ProposalVersion_proposalId_createdAt_idx" ON "ProposalVersion"("proposalId","createdAt");
CREATE UNIQUE INDEX "Project_projectNumber_key" ON "Project"("projectNumber");CREATE UNIQUE INDEX "Project_requestId_key" ON "Project"("requestId");CREATE UNIQUE INDEX "Project_proposalId_key" ON "Project"("proposalId");CREATE INDEX "Project_status_updatedAt_idx" ON "Project"("status","updatedAt");CREATE INDEX "Project_clientId_status_idx" ON "Project"("clientId","status");CREATE INDEX "Project_assignedAdminId_status_idx" ON "Project"("assignedAdminId","status");
CREATE INDEX "ProjectMilestone_projectId_status_dueDate_idx" ON "ProjectMilestone"("projectId","status","dueDate");CREATE INDEX "ProjectApproval_projectId_milestoneId_actedAt_idx" ON "ProjectApproval"("projectId","milestoneId","actedAt");CREATE INDEX "ProjectMessage_projectId_createdAt_idx" ON "ProjectMessage"("projectId","createdAt");CREATE INDEX "ProjectFile_projectId_category_createdAt_idx" ON "ProjectFile"("projectId","category","createdAt");CREATE INDEX "ProjectFileEvent_fileId_createdAt_idx" ON "ProjectFileEvent"("fileId","createdAt");CREATE INDEX "ProjectActivity_projectId_createdAt_idx" ON "ProjectActivity"("projectId","createdAt");
CREATE UNIQUE INDEX "ProjectInvoice_invoiceNumber_key" ON "ProjectInvoice"("invoiceNumber");CREATE INDEX "ProjectInvoice_projectId_status_dueDate_idx" ON "ProjectInvoice"("projectId","status","dueDate");CREATE INDEX "ProjectInvoice_clientId_status_idx" ON "ProjectInvoice"("clientId","status");CREATE UNIQUE INDEX "ProjectPaymentSubmission_idempotencyKey_key" ON "ProjectPaymentSubmission"("idempotencyKey");CREATE INDEX "ProjectPaymentSubmission_invoiceId_status_createdAt_idx" ON "ProjectPaymentSubmission"("invoiceId","status","createdAt");CREATE UNIQUE INDEX "ProjectPaymentReview_submissionId_key" ON "ProjectPaymentReview"("submissionId");CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt");

ALTER TABLE "ProjectRequest" ADD CONSTRAINT "ProjectRequest_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectRequest" ADD CONSTRAINT "ProjectRequest_assignedAdminId_fkey" FOREIGN KEY ("assignedAdminId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "ProjectRequestAttachment" ADD CONSTRAINT "ProjectRequestAttachment_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ProjectRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Proposal" ADD CONSTRAINT "Proposal_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ProjectRequest"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Proposal" ADD CONSTRAINT "Proposal_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Proposal" ADD CONSTRAINT "Proposal_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Proposal" ADD CONSTRAINT "Proposal_acceptedById_fkey" FOREIGN KEY ("acceptedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "ProposalVersion" ADD CONSTRAINT "ProposalVersion_proposalId_fkey" FOREIGN KEY ("proposalId") REFERENCES "Proposal"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProposalItem" ADD CONSTRAINT "ProposalItem_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "ProposalVersion"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Project" ADD CONSTRAINT "Project_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ProjectRequest"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Project" ADD CONSTRAINT "Project_proposalId_fkey" FOREIGN KEY ("proposalId") REFERENCES "Proposal"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Project" ADD CONSTRAINT "Project_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Project" ADD CONSTRAINT "Project_assignedAdminId_fkey" FOREIGN KEY ("assignedAdminId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ProjectMilestone" ADD CONSTRAINT "ProjectMilestone_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectMilestone" ADD CONSTRAINT "ProjectMilestone_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "ProjectApproval" ADD CONSTRAINT "ProjectApproval_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectApproval" ADD CONSTRAINT "ProjectApproval_milestoneId_fkey" FOREIGN KEY ("milestoneId") REFERENCES "ProjectMilestone"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectApproval" ADD CONSTRAINT "ProjectApproval_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProjectMessage" ADD CONSTRAINT "ProjectMessage_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectMessage" ADD CONSTRAINT "ProjectMessage_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "ProjectMessageAttachment" ADD CONSTRAINT "ProjectMessageAttachment_messageId_fkey" FOREIGN KEY ("messageId") REFERENCES "ProjectMessage"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectFile" ADD CONSTRAINT "ProjectFile_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectFile" ADD CONSTRAINT "ProjectFile_uploadedById_fkey" FOREIGN KEY ("uploadedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "ProjectFileEvent" ADD CONSTRAINT "ProjectFileEvent_fileId_fkey" FOREIGN KEY ("fileId") REFERENCES "ProjectFile"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectFileEvent" ADD CONSTRAINT "ProjectFileEvent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "ProjectActivity" ADD CONSTRAINT "ProjectActivity_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProjectInvoice" ADD CONSTRAINT "ProjectInvoice_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectInvoice" ADD CONSTRAINT "ProjectInvoice_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "ProjectInvoiceItem" ADD CONSTRAINT "ProjectInvoiceItem_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "ProjectInvoice"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectPaymentSubmission" ADD CONSTRAINT "ProjectPaymentSubmission_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "ProjectInvoice"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectPaymentSubmission" ADD CONSTRAINT "ProjectPaymentSubmission_paymentMethodId_fkey" FOREIGN KEY ("paymentMethodId") REFERENCES "PaymentMethod"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "ProjectPaymentSubmission" ADD CONSTRAINT "ProjectPaymentSubmission_submittedById_fkey" FOREIGN KEY ("submittedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "ProjectPaymentReview" ADD CONSTRAINT "ProjectPaymentReview_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "ProjectPaymentSubmission"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ProjectPaymentReview" ADD CONSTRAINT "ProjectPaymentReview_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
